mapper.select:
SELECT  FROM pet_cart_item
WHERE member_id = #{memberId}
ORDER BY create_time DESC, id DESC

mapper.update:
UPDATE pet_cart_item
SET quantity = #{quantity}, checked = #{checked}, pet_id = #{petId}, update_time = NOW()
WHERE id = #{id} AND member_id = #{memberId}

mapper.delete:
DELETE FROM pet_cart_item
WHERE member_id = #{memberId} AND sku_id IN
#{skuId}
